import { test, expect, type Page } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
async function visibleIds(page: Page): Promise<number[]> {
  return projectRows(page).evaluateAll((els) =>
    els.map((el) => Number(el.getAttribute('data-testid')!.replace('project-row-', ''))).sort((a, b) => a - b),
  );
}

test('probe combine', async ({ page }) => {
  await resetAndSeed({
    clients: [{ id: 1, name: 'Acme', email: 'a@a.test' }],
    projects: [
      { id: 1, name: 'P1', clientId: 1, status: 'ACTIVE' },
      { id: 2, name: 'P2', clientId: 1, status: 'ACTIVE' },
      { id: 3, name: 'P3', clientId: 1, status: 'ACTIVE' },
      { id: 4, name: 'P4', clientId: 1, status: 'ON_HOLD' },
    ],
    tags: [{ id: 1, name: 'urgent' }, { id: 2, name: 'backend' }],
    projectTags: [
      { projectId: 1, tagId: 1 },
      { projectId: 2, tagId: 1 },
      { projectId: 3, tagId: 2 },
      { projectId: 4, tagId: 1 },
    ],
  });
  await page.goto('/projects');
  await expect(projectRows(page)).toHaveCount(4);
  await page.getByTestId('project-status-filter').selectOption('ACTIVE');
  const tagVal = await page.getByTestId('project-tag-filter').locator('option').filter({ hasText: /urgent/i }).first().evaluate((el: HTMLOptionElement) => el.value);
  await page.getByTestId('project-tag-filter').selectOption(tagVal);
  await page.waitForTimeout(300);
  console.log('PROBE URL:', page.url());
  console.log('PROBE visibleIds after both filters:', JSON.stringify(await visibleIds(page)));
});

